//! `fab-slicebench`: the slicer speed harness (lane SLICEFAST).
//!
//! ```text
//! fab-slicebench gen DIR
//! fab-slicebench run CASE --models DIR --golden DIR [--ref DIR] [--threads N] [--out DIR]
//! fab-slicebench compare CASE --out DIR --ref DIR
//! ```
//! `gen` writes the bench parts (generated by `bench.rs`, never downloaded or
//! committed). `run` slices one case once and prints one JSON line: wall time
//! per phase (load, toolpaths, G-code writer, package) and per pipeline stage
//! (`toolpath::prof`, summed over threads), CPU time and cores used, peak RSS,
//! and hashes of the G-code and the package (same day: the package carries
//! the date) so every speed change can be checked byte-identical. With `--out`, the G-code is written there too.
//!
//! `compare` reads `run --out`'s G-code against the vendor reference run
//! (layers, estimate, filament, extents, wrong-direction arcs).
//!
//! Cases are the FABBENCH parts (`bench::CASES`, with the reference run's
//! placement and prime tower from `--ref`).

use makepad_fab_settings::profiles::{load_preset_file, JobSetup, Preset};
use makepad_fab_slice::{bench, check_inputs, finish, place, prepare_job, PlacedObject};
use makepad_fab_slicer::mesh::load_model;
use makepad_fab_slicer::source::MeshSource;
use makepad_fab_toolpath::{par, prof, ObjectInput};
use std::path::{Path, PathBuf};
use std::time::Instant;

fn arg(args: &[String], k: &str) -> Option<String> {
    args.iter().position(|a| a == k).and_then(|i| args.get(i + 1)).cloned()
}

fn setup_for(golden: &Path, case: &bench::BenchCase, ref_dir: &Path) -> Result<JobSetup, String> {
    let pre = |f: &str| -> Result<Preset, String> { Ok(Preset::from_flat(load_preset_file(&golden.join("inputs/presets").join(f))?)) };
    let mut setup = JobSetup {
        machine: pre("machine_H2D_0.4.json")?,
        process: pre(case.process)?,
        filaments: case.filaments.iter().map(|f| pre(f)).collect::<Result<_, _>>()?,
        filament_map: case.map.to_vec(),
        nozzle_volume_type: vec!["Standard".into(), "Standard".into()],
        bed_type: "Textured PEI Plate".into(),
        filament_map_mode: "Manual".into(),
        filament_colours: vec![None; case.filaments.len()],
    };
    makepad_fab_settings::family::of_profile(&setup.machine.values)?;
    // The reference run's prime tower (and purge matrix with two filaments),
    // from the head of its G-code.
    if let Ok(f) = std::fs::File::open(ref_dir.join("plate_1.gcode")) {
        use std::io::BufRead;
        let keys: &[&str] = if case.filaments.len() < 2 { &["wipe_tower_x", "wipe_tower_y"] } else { &["wipe_tower_x", "wipe_tower_y", "flush_volumes_matrix", "flush_multiplier", "flush_multiplier_fast"] };
        let head: Vec<String> = std::io::BufReader::new(f).lines().take(4000).map_while(Result::ok).collect();
        for key in keys.iter().copied() {
            let tag = format!("; {key} = ");
            if let Some(v) = head.iter().find_map(|l| l.strip_prefix(tag.as_str())) {
                if key.starts_with("flush_") {
                    setup.process.values.set_vec(key, v.trim().split(',').map(|x| x.trim().to_string()).collect());
                } else {
                    setup.process.values.set_str(key, v.trim());
                }
            }
        }
    }
    Ok(setup)
}

/// Object centres the reference run reports (result.json).
fn reference_centres(dir: &Path) -> Vec<(f64, f64)> {
    let Ok(bytes) = std::fs::read(dir.join("result.json")) else { return Vec::new() };
    let Ok(v) = makepad_strict_json::parse_depth(&bytes, 32) else { return Vec::new() };
    let num = |o: &makepad_strict_json::Value, k: &str| -> f64 {
        match o.get(k) {
            Some(makepad_strict_json::Value::F64(f)) => *f,
            Some(makepad_strict_json::Value::Int(i)) => *i as f64,
            _ => 0.0,
        }
    };
    let mut out = Vec::new();
    for p in v.get("sliced_plates").and_then(|p| p.as_arr()).into_iter().flatten() {
        for o in p.get("objects").and_then(|o| o.as_arr()).into_iter().flatten() {
            if let Some(b) = o.get("bbox") {
                out.push((num(b, "x") + num(b, "width") / 2.0, num(b, "y") + num(b, "depth") / 2.0));
            }
        }
    }
    out
}

/// FNV-1a, 64 bit: the G-code identity check.
fn fnv(bytes: &[u8]) -> u64 {
    let mut h: u64 = 0xcbf29ce484222325;
    for &b in bytes {
        h = (h ^ b as u64).wrapping_mul(0x100000001b3);
    }
    h
}

fn run(args: &[String], name: &str) -> Result<(), String> {
    let case = bench::CASES.iter().find(|c| c.name == name).ok_or_else(|| format!("unknown case {name}; cases: {}", bench::CASES.iter().map(|c| c.name).collect::<Vec<_>>().join(", ")))?;
    let golden = PathBuf::from(arg(args, "--golden").ok_or("--golden missing")?);
    let models = PathBuf::from(arg(args, "--models").ok_or("--models missing")?);
    let ref_dir = arg(args, "--ref").map(PathBuf::from).unwrap_or_else(|| golden.join("slices")).join(case.name);
    let threads: usize = arg(args, "--threads").and_then(|s| s.parse().ok()).unwrap_or(1);
    par::set_threads(threads);
    prof::enable(true);
    let setup = setup_for(&golden, case, &ref_dir)?;

    let t_all = Instant::now();
    let model = load_model(models.join(case.model).to_str().unwrap_or(""))?;
    let centres = reference_centres(&ref_dir);
    let stl = case.model.ends_with(".stl");
    let n_obj = model.objects.len();
    let mut objects = Vec::new();
    for (k, o) in model.objects.into_iter().enumerate() {
        // `load_model` welds and orients every mesh already.
        let mut mesh = o.mesh;
        if stl || centres.len() == n_obj {
            let (cx, cy) = centres.get(k).copied().unwrap_or((175.0, 160.0));
            place(&mut mesh, cx, cy);
        }
        let filament = if o.extruder > 0 { o.extruder as usize - 1 } else { 0 }.min(case.filaments.len() - 1);
        objects.push(PlacedObject { name: format!("{}_{k}", case.name), mesh, filament });
    }
    let tris: usize = objects.iter().map(|o| o.mesh.tris.len()).sum();
    let t_load = t_all.elapsed().as_secs_f64();

    let t0 = Instant::now();
    let job = prepare_job(&setup)?;
    let mut inputs = Vec::new();
    let mut boxes = Vec::new();
    for o in objects {
        boxes.push(o.mesh.bbox());
        inputs.push(ObjectInput { overrides: Vec::new(), name: o.name, source: Box::new(MeshSource::new(o.mesh)), filament: o.filament });
    }
    check_inputs(&job, &inputs)?;
    let _ = prof::take();
    let tp = makepad_fab_toolpath::generate(&inputs, &job);
    let t_toolpaths = t0.elapsed().as_secs_f64();
    let stages = prof::take();
    let names: Vec<String> = inputs.iter().map(|o| o.name.clone()).collect();
    let marks = std::sync::Mutex::new(Vec::<(Instant, f32)>::new());
    let t1 = Instant::now();
    let res = finish(job, std::sync::Arc::new(tp), &names, &boxes, &|f, _| marks.lock().unwrap().push((Instant::now(), f)), &|| false)?;
    let t_finish = t1.elapsed().as_secs_f64();
    let fstages = prof::take();
    let marks = marks.into_inner().unwrap();
    let at = |f: f32| marks.iter().find(|m| m.1 == f).map(|m| m.0);
    let t_writer = match (at(0.55), at(1.0)) {
        (Some(a), Some(b)) => (b - a).as_secs_f64(),
        _ => t_finish,
    };
    // The package is built on demand (Print / Export): timed apart, not
    // part of the slice's wall time.
    let wall = t_all.elapsed().as_secs_f64();
    let (rss, cpu) = bench::proc_usage();
    let t2 = Instant::now();
    let package = res.package()?;
    let t_package = t2.elapsed().as_secs_f64();

    if let Some(out) = arg(args, "--out") {
        let out = PathBuf::from(out);
        let _ = std::fs::create_dir_all(&out);
        std::fs::write(out.join(format!("{}.gcode", case.name)), &res.gcode).map_err(|e| e.to_string())?;
        std::fs::write(out.join(format!("{}.gcode.3mf", case.name)), &package).map_err(|e| e.to_string())?;
    }
    let num = |v: Option<f64>| v.map(|x| format!("{x:.2}")).unwrap_or_else(|| "null".into());
    let mut j = format!(
        "{{\"case\":\"{}\",\"threads\":{threads},\"tris\":{tris},\"layers\":{},\"wall_s\":{wall:.3},\"load_s\":{t_load:.3},\"toolpaths_s\":{t_toolpaths:.3},\"writer_s\":{t_writer:.3},\"package_s\":{t_package:.3}",
        case.name, res.stats.layers
    );
    j.push_str(",\"stages\":{");
    j.push_str(&stages.iter().filter(|(_, s)| *s > 0.0).map(|(k, v)| format!("\"{}\":{v:.3}", k.name())).collect::<Vec<_>>().join(","));
    j.push('}');
    j.push_str(",\"finish_stages\":{");
    j.push_str(&fstages.iter().filter(|(_, s)| *s > 0.0).map(|(k, v)| format!("\"{}\":{v:.3}", k.name())).collect::<Vec<_>>().join(","));
    j.push('}');
    let cores = cpu.map(|c| c / wall);
    j.push_str(&format!(",\"cpu_s\":{},\"cores\":{},\"rss_mb\":{}", num(cpu), num(cores), num(rss)));
    j.push_str(&format!(",\"gcode_bytes\":{},\"gcode_fnv\":\"{:016x}\",\"package_fnv\":\"{:016x}\",\"est_s\":{:.0},\"filament_g\":{:.2}}}", res.gcode.len(), fnv(res.gcode.as_bytes()), fnv(&package), res.stats.total_time, res.stats.filament_g.iter().sum::<f64>()));
    println!("{j}");
    Ok(())
}

/// Ours (from `run --out`) against the reference slice: layers, estimate,
/// filament, first layer and per-nozzle extents, wrong-direction arcs, and
/// the reference run's own stage times.
fn compare(args: &[String], name: &str) -> Result<(), String> {
    use makepad_fab_slice::golden;
    let case = bench::CASES.iter().find(|c| c.name == name).ok_or_else(|| format!("unknown case {name}"))?;
    let out = PathBuf::from(arg(args, "--out").ok_or("--out missing")?);
    let ref_dir = PathBuf::from(arg(args, "--ref").ok_or("--ref missing")?).join(case.name);
    let ours = std::fs::read_to_string(out.join(format!("{}.gcode", case.name))).map_err(|e| format!("ours: {e}"))?;
    let gold = std::fs::read_to_string(ref_dir.join("plate_1.gcode")).map_err(|e| format!("reference: {e}"))?;
    let head = |t: &str| golden::analyse(&t.lines().take_while(|l| !l.starts_with("; CONFIG_BLOCK_START")).collect::<Vec<_>>().join("\n")).header;
    let (ho, hg) = (head(&ours), head(&gold));
    let (_, ot) = golden::header_times(&ho);
    let (_, gt) = golden::header_times(&hg);
    // Per-filament lists ("43.33,14.19") are summed.
    let g = |h: &std::collections::BTreeMap<String, String>, k: &str| h.get(k).map(|v| v.split(',').filter_map(|x| x.split_whitespace().next()?.parse::<f64>().ok()).sum::<f64>()).unwrap_or(f64::NAN);
    let pct = |x: f64, y: f64| (x - y) / y * 100.0;
    println!("case {}", case.name);
    println!("  layers: ours {} ref {}", g(&ho, "total layer number"), g(&hg, "total layer number"));
    println!("  estimate: ours {ot:.0} s ref {gt:.0} s ({:+.1}%)", pct(ot, gt));
    let (fo, fg) = (g(&ho, "total filament weight [g]"), g(&hg, "total filament weight [g]"));
    println!("  filament: ours {fo:.2} g ref {fg:.2} g ({:+.1}%)", pct(fo, fg));
    let (fl, fgm) = (g(&ho, "total filament length [mm]"), g(&hg, "total filament length [mm]"));
    println!("  filament length: ours {fl:.0} mm ref {fgm:.0} mm ({:+.1}%)", pct(fl, fgm));
    let (ao, fo1, zo) = bench::nozzle_extents(&ours);
    let (ag, fg1, zg) = bench::nozzle_extents(&gold);
    println!("  first layer z: ours {zo:?} ref {zg:?}");
    let fmt = |e: [f64; 4]| if e[0] > e[2] { "unused".to_string() } else { format!("x {:.1}..{:.1} y {:.1}..{:.1}", e[0], e[2], e[1], e[3]) };
    for t in 0..2 {
        let side = if t == 0 { "left" } else { "right" };
        let dmax = |p: [f64; 4], q: [f64; 4]| if p[0] > p[2] || q[0] > q[2] { f64::NAN } else { (0..4).map(|i| (p[i] - q[i]).abs()).fold(0.0, f64::max) };
        println!("  {side} nozzle, all layers: ours {} | ref {} (max delta {:.2} mm)", fmt(ao[t]), fmt(ag[t]), dmax(ao[t], ag[t]));
        println!("  {side} nozzle, first layer: ours {} | ref {} (max delta {:.2} mm)", fmt(fo1[t]), fmt(fg1[t]), dmax(fo1[t], fg1[t]));
    }
    for (who, text) in [("ours", &ours), ("ref", &gold)] {
        let (n, bad, r, line) = bench::wrong_direction_arcs(text);
        println!("  arcs {who}: {n}, wrong direction {bad}{}", if bad > 0 { format!(" (largest radius {r:.1} mm, first at line {line})") } else { String::new() });
    }
    if let Ok(bytes) = std::fs::read(ref_dir.join("result.json")) {
        if let Ok(v) = makepad_strict_json::parse_depth(&bytes, 32) {
            let n = |o: Option<&makepad_strict_json::Value>| match o {
                Some(makepad_strict_json::Value::F64(f)) => *f,
                Some(makepad_strict_json::Value::Int(i)) => *i as f64,
                _ => f64::NAN,
            };
            let mut line = String::from("  reference stage times (ms):");
            for k in ["prepare_time", "export_time"] {
                line.push_str(&format!(" {k} {}", n(v.get(k))));
            }
            if let Some(p) = v.get("sliced_plates").and_then(|p| p.as_arr()).and_then(|p| p.first()) {
                for k in ["sliced_time", "make_perimeters_time", "infill_time", "generate_support_material_time"] {
                    line.push_str(&format!(" {k} {}", n(p.get(k))));
                }
                line.push_str(&format!(" | total_predication {:.0} s", n(p.get("total_predication"))));
            }
            println!("{line}");
        }
    }
    Ok(())
}

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let r = match args.first().map(|s| s.as_str()) {
        Some("gen") => args.get(1).ok_or_else(|| "gen DIR".to_string()).and_then(|d| bench::generate(Path::new(d))).map(|rep| print!("{rep}")),
        Some("run") => args.get(1).ok_or_else(|| "run CASE".to_string()).and_then(|c| run(&args, c)),
        Some("compare") => args.get(1).ok_or_else(|| "compare CASE".to_string()).and_then(|c| compare(&args, c)),
        _ => Err("usage: fab-slicebench gen DIR | run CASE --models DIR --golden DIR [--ref DIR] [--threads N] [--out DIR] | compare CASE --out DIR --ref DIR".into()),
    };
    if let Err(e) = r {
        eprintln!("fab-slicebench: {e}");
        std::process::exit(1);
    }
}
